ALTER TABLE "sv_runs" ADD COLUMN IF NOT EXISTS "extractor_version" text;
CREATE TABLE IF NOT EXISTS "sv_response_mentions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "run_id" uuid NOT NULL REFERENCES "sv_runs"("id"), "entity_type" text NOT NULL, "name" text NOT NULL, "ordinal_position" smallint, "match_method" text DEFAULT 'exact_term' NOT NULL, "extractor_version" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "sv_response_mentions_run_idx" ON "sv_response_mentions" ("run_id"); CREATE INDEX IF NOT EXISTS "sv_response_mentions_org_cycle_idx" ON "sv_response_mentions" ("organization_id", "cycle_id"); ALTER TABLE "sv_response_mentions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sv_response_mentions" ADD CONSTRAINT "sv_response_mentions_ordinal_positive" CHECK ("ordinal_position" IS NULL OR "ordinal_position" >= 1);
